const upsertFacilitiesWorkClass = `-- name: UpsertFacilitiesWorkClass :one

INSERT INTO facilities.work_class (
    tenant_id, code, name, requires_permit, requires_loto, active, note
) VALUES ($1, $2, $3, $4, $5,
          $6, $7)
ON CONFLICT (tenant_id, code) DO UPDATE SET
    name = EXCLUDED.name,
    requires_permit = EXCLUDED.requires_permit,
    requires_loto = EXCLUDED.requires_loto,
    active = EXCLUDED.active,
    note = EXCLUDED.note
RETURNING tenant_id, code, name, requires_permit, requires_loto, active, note, created_at
`

type UpsertFacilitiesWorkClassParams struct {
	TenantID       uuid.UUID
	Code           string
	Name           string
	RequiresPermit bool
	RequiresLoto   bool
	Active         bool
	Note           string
}

// Facilities engineering (SRS-FAC-001 … 011).
//
// Query names carry a Facilities prefix wherever the bare name would collide
// with another context's: sqlc's namespace is the whole of db/queries, so
// "InsertAsset" would be ambiguous against biomedical's.
func (q *Queries) UpsertFacilitiesWorkClass(ctx context.Context, arg UpsertFacilitiesWorkClassParams) (FacilitiesWorkClass, error) {
	row := q.db.QueryRow(ctx, upsertFacilitiesWorkClass,
		arg.TenantID,
		arg.Code,
		arg.Name,
		arg.RequiresPermit,
		arg.RequiresLoto,
		arg.Active,
		arg.Note,
	)
	var i FacilitiesWorkClass
	err := row.Scan(
		&i.TenantID,
		&i.Code,
		&i.Name,
		&i.RequiresPermit,
		&i.RequiresLoto,
		&i.Active,
		&i.Note,
		&i.CreatedAt,
	)
	return i, err
}
